const s = wb.getWorksheet('Main');
const data = s.getRange('A2:C47').getValues();
let deleted=0, rated=0, inserted=0;
// 3) rate change
data.forEach((r,i)=>{ if(r[0]==='National TV' && r[1]==='India'){ s.getRange(`G${i+2}`).setValue(180); rated++; } });
// bottom-up: delete, then insert after Ahmed Sons
for(let i=data.length-1;i>=0;i--){
  const row=i+2, [co,loc]=data[i];
  if(co==='Motorcycle' || (co==='Ahmed Sons' && loc==='Canada')){ s.getRange(`${row}:${row}`).delete(); deleted++; }
  else if(co==='Ahmed Sons'){ s.getRange(`${row+1}:${row+2}`).insert(); inserted+=2; }
}
// 5) lookup on data rows only
const v = s.getRange('A2:A70').getValues();
let looked=0;
v.forEach((r,i)=>{ if(r[0]!==null && r[0]!==undefined && r[0]!==''){ s.getRange(`M${i+2}`).setValue(`=VLOOKUP(C${i+2},Lookup!$A$2:$B$43,2,FALSE)`); looked++; } });
log({deleted,rated,inserted,looked});
